STEP = -0.04
MOVES = {'U': (-1, 0), 'R': (0, 1), 'D': (1, 0), 'L': (0, -1)}
SIDES = {'U': 'LR', 'D': 'LR', 'L': 'UD', 'R': 'UD'}
CELLS = [f'r{r}c{c}' for r in range(1, ROWS + 1) for c in range(1, COLS + 1)
         if f'r{r}c{c}' not in WALL]

def move(s, a):
